import graph.cycle.*;

public class CrossCheck {
    public static void main(String[] args) {
        CycleDetector kahn = CycleDetectorFactory.create(Algorithm.KAHN);
        CycleDetector dfs  = CycleDetectorFactory.create(Algorithm.DFS);

        // cyclic: 0->1->2->0, 2->3
        DirectedGraph cyclic = new DirectedGraph(4);
        cyclic.addEdge(0, 1); cyclic.addEdge(1, 2);
        cyclic.addEdge(2, 0); cyclic.addEdge(2, 3);

        // acyclic: 0->1->3, 0->2->3
        DirectedGraph acyclic = new DirectedGraph(4);
        acyclic.addEdge(0, 1); acyclic.addEdge(0, 2);
        acyclic.addEdge(1, 3); acyclic.addEdge(2, 3);

        System.out.println("cyclic  - KAHN=" + kahn.hasCycle(cyclic)  + " DFS=" + dfs.hasCycle(cyclic));
        System.out.println("acyclic - KAHN=" + kahn.hasCycle(acyclic) + " DFS=" + dfs.hasCycle(acyclic));
    }
}
